export type ErrCallback = (err?:Error)=>void;
export type MediaRecordCallback = (err:Error, mediaRecord?:any)=>void;
export type StreamCallback = (err:Error, stream?:NodeJS.ReadWriteStream)=>void;
export class SingletonEnforcer{};


class MediaManagerService extends HTTPService {
    private static _instance:MediaManagerService;
    private _kbServiceUrl:string;
    private _extraRecord:RegistrationRecord;
    private _extraIntervalId;
    private _jscKeyClient;
    private _jscMediaClient;
    private _loopId:string;
    private _keyDir:string;
    private _noEncryption:boolean;
    private _symmetricalKey:any;
    private __mediaRootDir:string;
    private __onRobot:boolean;


    public static createInstance(options:ServiceOptions, rootDir:string):MediaManagerService {
        return new MediaManagerService(new SingletonEnforcer(), options, rootDir);
    }
    public static get instance():MediaManagerService {
        return MediaManagerService._instance;
    }


    constructor(enforcer:SingletonEnforcer, options:ServiceOptions, rootDir:string) {
        super('media-manager', options, rootDir);  // TODO rename back to 'media-manager'
        if (MediaManagerService._instance) {
            throw new Error('MediaManagerService is a singleton');
        }
        MediaManagerService._instance = this;
        log.info('initialized');
    }


    public init(callback: (err?:Error)=>void) {
        super.init( (err?:Error) => {
            if (err) {
                callback(err);
            } else {
                // we absorbed the media-proxy, so also register
                // that service name for backwards compatability
                this._registerExtraServiceName('media-proxy', (err) => {
                    if (err) {
                        callback(err);
                    } else {
                        RegistryClient.instance.getRecordByName('kb', (err, record:RegistrationRecord) => {
                            log.iferr(err, 'RegistryClient.instance.getRecordByName');
                            if (!err) {
                                this._kbServiceUrl = `http://${record.host}:${record.port}`;
                            }
                            callback(err);
                        });
                    }
                });
            }
        });
    }


    public routes(url:Router) {
        super.routes(url);
        url.post('/media-manager/upload', this._onUpload.bind(this));
        url.post('/media-manager/download', this._onDownload.bind(this));
        url.post('/media-manager/delete', this._onDelete.bind(this));
        url.get('/proxy/media/photo/get', (req:JiboServerRequest, res:JiboServerResponse) => {
            this._onPhotoGet(req, res);
        });
    }


    public destroy() {
        super.destroy();
        clearInterval(this._extraIntervalId);
    }


    private _onUpload(req:JiboServerRequest, res:JiboServerResponse) {
        let params = req.body;
        let filename = this._filename(params);
        log.info('_onUpload', params);

        this._setupJSCClients();
        this._setupLoopId( (err) => {
            if (!err) {
                fs.stat(filename, (err, stats) => {
                    let newErr;
                    if (err) {
                        newErr = new Error('stat failed '+filename+' '+err);
                        log.error(newErr);
                        this.finish(res, newErr);  // 500
                    } else if (!stats.isFile()) {
                        newErr = new Error('not a file '+filename);
                        log.error(newErr);
                        this.finish(res, newErr);  // 500
                    } else {
                        this._getMediaRecord(params.contentID, (err, mediaRecord) => {
                            if (mediaRecord) {
                                log.warn('File already exists on server', params.contentID);
                                if (!params.keepLocal) {
                                    fs.unlink(filename, (err) => {
                                        log.iferr(err, 'could not unlink file');
                                    });
                                }
                                this.finishNoContent(res, 204);
                            } else {
                                let rstream = fs.createReadStream(filename);
                                
                                this._encryptStream(rstream, (err, rstream) => {
                                    let createParams = {
                                        loopId: this._loopId,
                                        body: rstream,
                                        path: params.contentID,
                                        type: params.type,
                                        isEncrypted: true,
                                        reference: params.reference ? params.reference : undefined
                                    };

                                    if (this._noEncryption) {
                                        createParams.isEncrypted = false;
                                    }
                                    
                                    this._jscMediaClient.create(createParams, (err, data) => {
                                        log.iferr(err, 'Media#create');
                                        if (!err) {
                                            if (!params.keepLocal) {
                                                fs.unlink(filename, (err) => {
                                                    log.iferr(err, 'could not unlink file');
                                                });
                                            }
                                        }
                                        this.finishNoContent(res, 204);
                                    });
                                });
                            }
                        });
                    }
                });
            } else {
                this.finish(res, err);  // 500
            }
        });
    }


    private _onDownload(req:JiboServerRequest, res:JiboServerResponse) {
        let params = req.body;
        let filename = this._filename(params);

        fs.stat(filename, (err, stats) => {
            if (!err) {
                log.info('File already exists', filename);
                this.finishNoContent(res, 204);
            } else {
                this._downloadFromCloud(params, (err) => {
                    if (err) {
                        if (err.name === 'EnoentError') {
                            this.finishNoContent(res, 404);
                        } else {
                            this.finish(res, err);  // 500
                        }
                    } else {
                        this.finishNoContent(res, 204);
                    }
                });
            }
        });
    }


    private _onDelete(req:JiboServerRequest, res:JiboServerResponse) {
        let params = req.body;
        let filename = this._filename(params);

        if (params.deleteLocal) {
            let stats = fs.statSync(filename);
            if (!stats) {
                log.error('Stat failed', filename);
            } else if (!stats.isFile()) {
                log.error('Not a file', filename);
            } else {
                fs.unlinkSync(filename);
                log.info('deleted file: ', filename);
            }
        }

        if (params.deleteRemote) {
            this._setupJSCClients();
            this._jscMediaClient.remove({paths: [params.contentID]}, (err, data) => {
                if (err) {
                    log.error('Failed (with error) to delete:', params.contentID, err);
                } else if (data.length === 0) {
                    log.error('Failed to delete:', params.contentID);
                } else {
                    log.info('Successful deletion', params.contenID);
                }
                this.finishNoContent(res, 204);
            });
        } else {
            this.finishNoContent(res, 204);
        }
    }


    // //if we're in the simulator (i.e. not unit tests) then upload to the cloud
    // if(this.options.serverMediaService) {
    //     this.updateMedia(ret, (err) => {
    //         if(err) {
    //             return this.sendJson(res, {error: err.message}, 500);
    //         }
    //         this.sendJson(res, ret);
    //     });
    // }


    private _downloadFromCloud(params, callback:ErrCallback) {
        let downloadFilename = this._filename(params, true);
        let filename = this._filename(params);
        this._setupJSCClients();
        this._getMediaRecord(params.contentID, (err, mediaRecord) => {
            if (err) {
                log.error('Error getting file from server', params.contentID, err);
                callback(err);
                //this.finishNoContent(res, 404);
            } else {
                if (mediaRecord) {
                    if (!fs.existsSync(this._mediaRootDir)) {
                        mkdirp.sync(this._mediaRootDir);
                    }
                    let file = fs.createWriteStream(downloadFilename, {encoding: 'binary'});
                    https.get(mediaRecord.url, (response) => {
                        this._decryptStream(response, mediaRecord.isEncrypted, params.contentID, (err, stream) => {
                            stream.pipe(file);

                            file.on('finish', () => {
                                //remove the ".DL." prefix from the name to
                                //indicate that the download completed
                                fs.rename(downloadFilename, filename, (err) => {
                                    log.info('Done downloading');
                                    if (err) {
                                        log.error(err, 'fs.rename '+downloadFilename+', '+filename);
                                    }
                                    callback(err);
                                });
                            });
                        });
                    });
                } else {
                    let err = new Error('could not download, file does not exist on server '+params.contentID);
                    err.name = 'EnoentError';
                    log.error(err);
                    callback(err);
                }
            }
        });
    }

    
    private _onPhotoGet(req:JiboServerRequest, res:JiboServerResponse, secondTry?:boolean) {
        let id = req.query.id;
        // let immediate = true;
        let mediaType = 'image';  //jibo.media.mediaManagerService.MediaType.image;
        let filename = this._filename({type: mediaType, contentID: id});
        fs.open(filename, 'r', (err, fd) => {
            if (err) {
                if (err.code === 'ENOENT') {
                    if (!secondTry) {
                        this._downloadFromCloud({type: mediaType, contentID: id}, (err) => {
                            if (err) {
                                let newErr = new Error('download failed '+id+' '+err);
                                log.error(newErr);
                                if (err.name === 'EnoentError') {
                                    this.finishNoContent(res, 404);
                                } else {
                                    this.finish(res, newErr);  // 500
                                }
                            } else {
                                this._onPhotoGet(req, res, true);
                            }
                        });
                    } else {
                        let err = new Error('could not find file after downloaing it from cloud!');
                        log.error(err);
                        this.finish(res, err);  // 500
                    }
                } else {
                    let newErr = new Error('error opening file '+filename+' '+err);
                    log.error(newErr);
                    this.finish(res, newErr);  // 500
                }
            } else {
                let data = fs.createReadStream(null, {fd: fd});
                res.setHeader('Content-Type', 'image/jpeg');
                data.pipe(res);
            }
        });
    }        
                    

    private _getMediaRecord(id, callback:MediaRecordCallback) {
        this._jscMediaClient.get({paths: [id]}, (err, data) => {
            log.iferr(err, 'Media#get');
            if (err || data === null || data.length === 0) {
                callback(err);
            } else {
                let mediaRecord;
                for (let i=0; i<data.length; i++) {
                    if (data[i].path === id) {
                        mediaRecord = data[i];
                        break;
                    }
                }
                callback(null, mediaRecord);
            }
        });
    }


    private _encryptStream(stream, callback:StreamCallback) {
        if (this._noEncryption) {
            process.nextTick( () => {callback(null, stream);} );
        } else {
            this._setupSymmetricalKey( (err) => {
                if (err) {
                    callback(err);
                } else {
                    let params = {Key: this._symmetricalKey, Body: stream};
                    let encStream = this._jscKeyClient.encryptSymmetricStream(params);
                    callback(null, encStream);
                }
            });
        }
    }


    private _decryptStream(stream, isEncrypted, id, callback:StreamCallback) {
        if (!isEncrypted || this._noEncryption) {
            if (isEncrypted) {
                log.warn('cannot decrypt encrypted media item', id);
            }
            process.nextTick( () => {
                callback(null, stream);
            });
        } else {
            this._setupSymmetricalKey( (err) => {
                if (err) {
                    callback(err);
                } else {
                    let params = {Key: this._symmetricalKey, Body: stream};
                    let decStream = this._jscKeyClient.decryptSymmetricStream(params);
                    callback(null, decStream);
                }
            });
        }
    }

    private _setupSymmetricalKey(callback) {
        this._setupLoopId( (err) => {
            if (err) {
                callback(err);
            } else {
                if (this._symmetricalKey) {
                    process.nextTick(callback);
                } else {
                    this._jscKeyClient.loadSymmetricalKey({loopId: this._loopId}, (err, symmKey) => {
                        if (err || symmKey === null) {
                            if (!err) {
                                err = new Error('loaded key was null');
                            }
                            log.error('failed to load key', err);
                        } else {
                            this._symmetricalKey = symmKey;
                        }
                        callback(err);
                    });
                }
            }
        });
    }

    private _setupLoopId(callback) {
        this._setupJSCClients();
        if (this._loopId) {
            process.nextTick(callback);
        } else {
            const loopClient = new JSC.Loop();
            loopClient.list((err, data) => {
                if (err) {
                    callback(err);
                } else if (!data || data.length === 0) {
                    callback(new Error('failed to lookup loop id, no loop'));
                } else if (data.length > 1) {
                    callback(new Error('multiple loops found, can not deal with this.'));
                } else {
                    this._loopId = data[0].id;
                    callback();
                }
            });
        }
    }


    private _setupJSCClients() {
        if (!this._jscMediaClient) {
            // set credentials first before creating client or
            // the client won't have them
            let filename;
            if (this._onRobot) {
                filename = '/var/jibo/credentials.json';
            } else {
                filename = path.join(process.env.HOME || process.env.USERPROFILE,
                                     '.jibo', 'credentials.json');
            }
            let credentials;
            try {
                let data = fs.readFileSync(filename, 'utf8');
                credentials = JSON.parse(data);
            } catch (e) {
                log.error('could not read/parse credentials file', filename);
            }
            if (credentials) {
                JSC.config.update(credentials);
                //JSC.config.update({maxRetries: 1});  // default is 3 which is too many
            }
            this._jscMediaClient = new JSC.Media();
        }

        if (!this._jscKeyClient) {
            this._jscKeyClient = new JSC.Key();
            this._setupJSCKeys();
        }
    }


    private _setupJSCKeys() {
        if (!this._keyDir) {
            if (this._onRobot) {
                this._keyDir = '/var/jibo/keys';
                // always, always, always encrypt on the robot
                this._noEncryption = false;
            } else {
                this._keyDir = path.join(process.env.HOME || process.env.USERPROFILE,
                                         '.jibo', 'keys');
                // only use keys in simulator if available
                if (fs.existsSync(path.join(this._keyDir, 'keypair.json'))
                    && this._jscKeyClient.loadSymmetricalKey)
                {
                    this._noEncryption = false;
                } else {
                    this._noEncryption = true;
                }
            }

            // Key storage overload
            JSC.Key.prototype.storage = {
                load: (name, callback) => {
                    let filename = path.join(this._keyDir, name + '.json');
                    fs.readFile(filename, {encoding: 'utf8'}, callback);
                },
                save: (name, value, callback) => {
                    let filename = path.join(this._keyDir, name + '.json');
                    fs.writeFile(filename, value, callback);
                }
            };
        }
    }


    private _registerExtraServiceName(extraName:string, callback:ErrCallback) {
        const REFRESH_DURATION = 10000;
        const TTL = 30;
        this._extraRecord = {
            name: extraName,
            host: 'localhost',
            port: this.port,
            path: '/',
            //ttl: this.ttl,  // damn, ttl is private
            ttl: TTL,
            tls: ''
        };
        // since the registry service is persistent on the robot, clear out
        // any old records first
        RegistryClient.instance.deleteRecord(this._extraRecord, (error:Error) => {
            if (error) {
                log.error('RegistryClient.deleteRecord', error);
            }
            RegistryClient.instance.addNewRecord(this._extraRecord, (error:Error) => {
                //set a refresh of 10 seconds
                //this._extraIntervalId = setInterval(this._extraRefresh.bind(this), this.refreshDuration);  // refreshDuration is private
                this._extraIntervalId = setInterval(this._extraRefresh.bind(this), REFRESH_DURATION);
                // don't report upwards any errors
                // if there is a registry problem (e.g. registry service isn't up)
                // it should resolve itself during the refreshes
                callback();
            });
        });
    }


    private _extraRefresh() {
        RegistryClient.instance.editRecord(this._extraRecord, (error) => {
            if (error) {
                // [SDK-848] if registry service restarted the entry
                // will have disappeared and has to be added back
                log.info('readding registry record', this._extraRecord);
                RegistryClient.instance.addNewRecord(this._extraRecord, () => {
                    return;
                });
            } else {
                return;
            }
        });
    }


    private _filename(params, download=false) {
        let extension = '';
        if (params.type === 'recording') {
            extension = '.mp4';
        }
        if (params.type === 'image' ||
            params.type === 'thumb' ||
            params.type === 'thumb_robot') {
            extension = '.jpg';
        }
        if (download) {
            return path.join(this._mediaRootDir, '.DL.' + params.contentID + extension);
        } else {
            return path.join(this._mediaRootDir, params.contentID + extension);
        }
    }


    private get _mediaRootDir():string {
        if (!this.__mediaRootDir) {
            if (this._onRobot) {
                this.__mediaRootDir = '/opt/jibo/Photos';
            } else {
                this.__mediaRootDir =
                    path.join(process.env.HOME || process.env.USERPROFILE, '.jibo', 'photos');
            }
        }
        return this.__mediaRootDir;
    }


    private get _onRobot():boolean {
        if (this.__onRobot === undefined) {
            // we might need a better centralized way to tell if we are on the robot FIXME
            this.__onRobot = (process.platform === 'linux'
                              && process.arch === 'arm'
                              && fs.existsSync('/var/jibo'));
        }
        return this.__onRobot;
    }
}


export default MediaManagerService;
