import data from './data';


type DataCallback = (err?, data?)=>void;

interface Params {
    ids?: string[];
    [x: string]: any;
}

function callAsync(callback:Function, ...args:any[]) {
    process.nextTick( () => {
        callback(...args);
    });
}


// example calls to emulate:
// JSC.config.update(credentials);
class config {
    public static update(params:Params) {
        console.log('SSC config.updaate', params);
    }
}


// example calls to emulate:
// account = new JSC.Account()
//  account.update(params, (err, data) => {
//  account.get({ids: loopAccountIds}, (err, data) => {
//  account.get({}, (err, data) => {
class Account {
    public update(params:Params, callback:DataCallback) {
        console.log('SSC Account.update', params);
        callAsync(callback, null);
    }


    public get(params:Params, callback:DataCallback) {
        if (!params.ids) {
            callAsync(callback, null, [data.accounts[1]]);  // 0 for owner credentials, 1 for robot
        } else {
            // warning: doesn't actually filter by `ids` parameter
            callAsync(callback, null, data.accounts);
        }
    }
}


// example calls to emulate:
// loop = new JSC.Loop()
//  loop.list((err, data) => {
//  loop.list({}, (err, data) => {
//  loop.setEnrollment(params, (err, data) => {
class Loop {
    public list(params:Params, callback:DataCallback);
    public list(callback:DataCallback);
    public list(params:Params|DataCallback, callback?:DataCallback) {
        if (!callback && typeof params === 'function') {
            callback = <DataCallback>params;
            params = null;
        }
        callAsync(callback, null, data.loop);
    }


    public setEnrollment(params:Params, callback:DataCallback) {
        callAsync(callback, null);
    }
    public loopSuspend(params:Params, callback:DataCallback) {
        callAsync(callback, null);
    }
}


// example calls to emulate:
// media = new JSC.Media()
//  media.create(params, done);
//  media.list(params, done);
class Media {
    public create(params:Params, callback:DataCallback) {
        callAsync(callback, null);
    }


    public list(params:Params, callback:DataCallback) {
        callAsync(callback, null, []);
    }
}


// example calls to emulate:
// notification = new JSC.Notification()
//  notification.connect(params, done);
class Notification {
    public connect(params:Params, callback:DataCallback) {
        class Hub {
            public on(name:string, callback:Function) {
                return;
            }
        }
        let hub = new Hub();
        callAsync(callback, null, hub);
    }
}


// example calls to emulate:
// person = new JSC.Person()
//  this.personClient.listHolidays({loopId: loopId}, (err, data) => {
class Person {
    public listHolidays(params:Params, callback:DataCallback) {
        callAsync(callback, null, data.holidays);
    }
}


export class JSC {
    public static config = config;
    public static Account = Account;
    public static Loop = Loop;
    public static Media = Media;
    public static Notification = Notification;
    public static Person = Person;
};
