import path = require('path');
import findRoot = require('find-root');
import {EventEmitter} from 'events';
import Log = require('jibo-log');

import {RegistryClient} from 'jibo-service-framework';
import SystemManagerClient from '../clients/SystemManagerClient';
import MediaManagerService from '../services/media-manager-service/MediaManagerService';

let log = new Log('mms-process');


//console.log('before quit');
class MMSProcess extends EventEmitter {

    constructor() {
        super();

        // process.on('SIGINT', function(event) {
        //     console.log("Caught interrupt signal");
        //     setTimeout(() => {
        //         console.log('REALLY EXIT');
        //         process.exit();
        //     }, 5000);
        // });

        let httpRoot:string = path.join(findRoot(__dirname), 'static/media-manager-service');

        RegistryClient.createInstance('127.0.0.1', 8181);
        SystemManagerClient.createInstance('127.0.0.1', 8585);

        MediaManagerService.createInstance({port: 8488}, httpRoot);
        MediaManagerService.instance.init( (err) => {
            log.iferr(err, 'error initing MediaManagerService');

            let sem = require('node-semaphore');
            console.log('SEMAPHORE', 'pid', process.pid);
            let s = sem.Semaphore('/jibo-startup-' + process.pid + '.event');
            s.post();
            
            log.debug('MMS Started');
        });
    }
}

export default function() {
    return new MMSProcess();
}
